\u004a\u0060\u0079\u0062\u005a\u002a\u0075\u006c\u0066\u0057\u0030\u005c\u0035\u003a\u0052\u0036\u0075\u006d\u006c\u0058\u0076\u004c\u0049\u0038\u0038\u0063\u0058\u0041\u0059\u0054\u0056\u002c\u0046\u005e\u007d\u0060\u006f\u0067\u007e\u002c\u0049\u0055\u005d\u0076\u0031\u0061\u005d\u0031\u0048\u0029\u0028\u007b\u0053\u005d\u0061\u0022\u0030\u0068\u006a\u0030\u004e\u004a\u0047\u0055\u005b\u002a\u0024\u004e\u002c\u0028\u0054\u004d\u004b\u0043\u0077\u0053\u0061\u0057\u0076\u0035\u0028\u006b\u0077\u0039\u006d\u0037\u0029\u004f\u0066\u0022\u0046\u0042\u002c\u0047\u002d\u003e\u0022\u005c\u007d\u0029\u0067\u002a\u0053\u0063\u0050\u0076\u0026\u006b\u007c\u0067\u0061\u0052\u0034\u006d\u0044\u0059\u003e\u0032\u006e\u002d\u0024\u002a\u0029\u002a\u0033\u0034\u005e\u004e\u0056\u0058\u0038\u0056\u002e\u002b\u003a\u0058\u004b\u007c\u0045\u0049\u0048\u0035\u0034\u0078\u0027\u0025\u0058\u0029\u005f\u0037\u0041\u0059\u003f\u0028\u0048\u0068\u0041\u0041\u0079\u0045\u0042\u0060\u002c\u0071\u005f\u0044\u0053\u005a\u0031\u0037\u006d\u0075\u0034\u0041\u0064\u005e\u0020\u006d\u007b\u0069\u0052\u002e\u003b\u0039\u004d\u0068\u004d\u007b\u005a\u006d\u0036\u002f\u0069\u0033\u005d\u0058\u004b\u0058\u0047\u0074\u006f\u003e\u0058\u0051\u005e\u0073\u0038\u0034\u0078\u004b\u004b\u0051\u0048\u0024\u007e\u005f\u005e\u005f\u0076\u0068\u0055\u0062\u0061\u007d\u0039\u006d\u0074\u0064\u0076\u0075\u0055\u0066\u0054\u0051\u0064\u0020\u003d\u004b\u0035\u0051\u007c\u0020\u002d\u005b\u0074\u0025\u007c\u006b\u005e\u0053\u0045\u005b\u0020\u0070\u0072\u003b\u0073\u0047\u0030\u0040\u005f\u002c\u0054\u0071\u006d\u0054\u0079\u0038\u003a\u0024\u0074\u005f\u006e\u0023\u0076\u0073\u0022\u0036\u005c\u006d\u006c\u006f\u0048\u005a\u0030\u006d\u0068\u006f\u0076\u0054\u0043\u007c\u0060\u0036\u0048\u004a\u004c\u0055\u0077\u0027\u0023\u0059\u0063\u0077\u0025\u0047\u007e\u006c\u006f\u0030\u0020\u006c\u0041\u0025\u0038\u006c\u006a\u0053\u004e\u004c\u002a\u0059\u0062\u005a\u0030\u0023\u0054\u007c\u004a\u006a\u0075\u0051\u002d\u0063\u007d\u0077\u007e\u005f\u0020\u005b\u0044\u0023\u003e\u0073\u004e\u004d\u0068\u0062\u0068\u006b\u007a\u0060\u0067\u004a\u0072\u002c\u005f\u0051\u0061\u0043\u0036\u006b\u0029\u002d\u003b\u0057\u005c\u0037\u0055\u0056\u0071\u004f\u004e\u0023\u003b\u0041\u0048\u004b\u005c\u002b\u0020\u004f\u0038\u002a\u0050\u004d\u0033\u003f\u0028\u007d\u005e\u0079\u0049\u0028\u005f\u0050\u0035\u004f\u0027\u0041\u0051\u0073\u0034\u0049\u002e\u0026\u006c\u004b\u0037\u0059\u0039\u0050\u0054\u0067\u0057\u0056\u0024\u007c\u0023\u004d\u0042\u002c\u0065\u004f\u006f\u007b\u0069\u0043\u0074\u0039\u0079\u0054\u0036\u004b\u002b\u005e\u007a\u002f\u006c\u003a\u005b\u006f\u003b\u0047\u0057\u0029\u0035\u0048\u0041\u0050\u006a\u0041\u0055\u0042\u004c\u005a\u006a\u0054\u0056\u007b\u005a\u0049\u007a\u0074\u002d\u002c\u0060\u0057\u0043\u007a\u0034\u0022\u0026\u0024\u005f\u0027\u0056\u0023\u0067\u006e\u007e\u0078\u007d\u0077\u003e\u0028\u0023\u0032\u0031\u0046\u006b\u002d\u0076\u0074\u0061\u0076\u0078\u005f\u0063\u003f\u0047\u007e\u003e\u0069\u002c\u0040\u0065\u004c\u0020\u0073\u004a\u0073\u002c\u003b\u0055\u0079\u0053\u005e\u0030\u0045\u004c\u0056\u0037\u002c\u005c\u0028\u0072\u0020\u003a\u002f\u0064\u0053\u004d\u0046\u006a\u0067\u0032\u006a\u0023\u005a\u0069\u006f\u003e\u0048\u005f\u0033\u0063\u0030\u002c\u005a\u002b\u002d\u007b\u0060\u005c\u0033\u0064\u002e\u0031\u0054\u0045\u0059\u0022\u0051\u003b\u004c\u002e\u0031\u005a\u005d\u0039\u0048\u0035\u0026\u002c\u0033\u005c\u0061\u0074\u003b\u006a\u0075\u005d\u006c\u007c\u0076\u0027\u0059\u0044\u0066\u0042\u003a\u0079\u0078\u0029\u0056\u005f\u0024\u0029\u0048\u0036\u007d\u0028\u004d\u0056\u006c\u0069\u003d\u0038\u003b\u006b\u0048\u004c\u0044\u002a\u0054\u0054\u007c\u0047\u002a\u0045\u007a\u0063\u0057\u0052\u002f\u006a\u0070\u0067\u0036\u003e\u0040\u003d\u0023\u0070\u0023\u0048\u007d\u005f\u0056\u0059\u0047\u005c\u0072\u007a\u0051\u0034\u0024\u004e\u0059\u004b\u0056\u0052\u0035\u0077\u0054\u007e\u0042\u005c\u0043\u0033\u0035\u0078\u007a\u0033\u007b\u0050\u0044\u007c\u003a\u0035\u0060\u005a\u0076\u0057\u003d\u002d\u0043\u0024\u0026\u004a\u0021\u0042\u0071\u0070\u0039\u0027\u0028\u0046\u0036\u005c\u0059\u0061\u0040\u004f\u004b\u007e\u003a\u006c\u0030\u0045\u0034\u007e\u0073\u0020\u0027\u0047\u0022\u002b\u0056\u006d\u0045\u0025\u004d\u0067\u005b\u0027\u0034\u003c\u0045\u0075\u0020\u003c\u003b\u0062\u0028\u0043\u0021\u004a\u0075\u0066\u0075\u006b\u0071\u003d\u005b\u0059\u002e\u0046\u0041\u0048\u0047\u0022\u0048\u0043\u0026\u003f\u003e\u0058\u002f\u005b\u0073\u002a\u0027\u0052\u005e\u0037\u0078\u007c\u0056\u0027\u006a\u0040\u002e\u0023\u0071\u0021\u007d\u0074\u007a\u0031\u0042\u0048\u0033\u0044\u0071\u0025\u0073\u0054\u0070\u007c\u0071\u0070\u0077\u0057\u007d\u006f\u006f\u0075\u0042\u007e\u006a\u004d\u0029\u0075\u0054\u004f\u007e\u0031\u0063\u0043\u005c\u0027\u0029\u006b\u0038\u0059\u006e\u006f\u0035\u0040\u0036\u002a\u0076\u005f\u0043\u005c\u0060\u007a\u003f\u0038\u0047\u0038\u0050\u004e\u0079\u005e\u0058\u0062\u0044\u005b\u0042\u0020\u003e\u002a\u0064\u0039\u0035\u004a\u006f\u0060\u002f\u0047\u0072\u005f\u006b\u0065\u004b\u004e\u0031\u0036\u006c\u0039\u0050\u004e\u006f\u005b\u005a\u0074\u0073\u006a\u0029\u003e\u007a\u0035\u0042\u0048\u007b\u0064\u005a\u005d\u0052\u0033\u005d\u007e\u0020\u0029\u0079\u0070\u004e\u0049\u0052\u0039\u0035\u0048\u002f\u004b\u006a\u002c\u0031\u0020\u0051\u0037\u005c\u005d\u0069\u0046\u0021\u0030\u003b\u0046\u0069\u002b\u0054\u006c\u0034\u0051\u0036\u0033\u004b\u0035\u003b\u004c\u004a\u0062\u0044\u0067\u0040\u0054\u0040\u007d\u003e\u0030\u005b\u0023\u0045\u0040\u0036\u0046\u0039\u003e\u0057\u005f\u007c\u007e\u0050\u0023\u005e\u0059\u0024\u0028\u0053\u007d\u005c\u0076\u0033\u0037\u0054\u0046\u006f\u0055\u0028\u0041\u0023\u0030\u0073\u0037\u0052\u0064\u0023\u0073\u005e\u0065\u0074\u007e\u005e\u006f\u0026\u0027\u0071\u006f\u0065\u004f\u0056\u0079\u007a\u0041\u0036\u0069\u0060\u002d\u0058\u0026\u0040\u003f\u0039\u003a\u0027\u0037\u004f\u0070\u003c\u0065\u0051\u0045\u0020\u0027\u003d\u005e\u0079\u002c\u0061\u006b\u005a\u0050\u004e\u0024\u0065\u003c\u007c\u002b\u0047\u0036\u0048\u005d\u0045\u0065\u003c\u0068\u004a\u0035\u0079\u0044\u003e\u005f\u007d\u0036\u0036\u007a\u002c\u006f\u0022\u0020\u006a\u006f\u0048\u0049\u0047\u0056\u0071\u005a\u004b\u0033\u002e\u0073\u0068\u0049\u005d\u0049\u0078\u0029\u0055\u0057\u007c\u004d\u0059\u0030\u0031\u002b\u0051\u006b\u0074\u0058\u004b\u0058\u0072\u0076\u007e\u003b\u006f\u0046\u0064\u005e\u0051\u0052\u0054\u005a\u0054\u006b\u0027\u006f\u0029\u0053\u0062\u004a\u0024\u004f\u0068\u007a\u0033\u0079\u002a\u0079\u006d\u0049\u006b\u003c\u0024\u006e\u0062\u0047\u0071\u0025\u0064\u0040\u0062\u007e\u003e\u0023\u004b\u0021\u005e\u0078\u0037\u0042\u004e\u0029\u003b\u0057\u0078\u0033\u0027\u0057\u0028\u0023\u0030\u0067\u0052\u0041\u0075\u005b\u0043\u0043\u0033\u006e\u0052\u0074\u0048\u0055\u007c\u0058\u0059\u003a\u0042\u0047\u0068\u004e\u0075\u0046\u0029\u0028\u004a\u002c\u0070\u005b\u0032\u0067\u007e\u003c\u0047\u0052\u0030\u0032\u007a\u0046\u0041\u0020\u0077\u004b\u0036\u006b\u004f\u004d\u0030\u005a\u007e\u005e\u0028\u005e\u0067\u0078\u002b\u0071\u0074\u0021\u006a\u0023\u0074\u0043\u0063\u0041\u002e\u0070\u002b\u007c\u0031\u0068\u0065\u0034\u007e\u007e\u002c\u007e\u002b\u0022\u0025\u007b\u0031\u007d\u0047\u002b\u007e\u005d\u006f\u0025\u0070\u005f\u0074\u0032\u0023\u0030\u005b\u002a\u006c\u002e\u004e\u0029\u002e\u0038\u0063\u003b\u0064\u0043\u006d\u0035\u0036\u0021\u0057\u003b\u0070\u005a\u007b\u0053\u0053\u007d\u0069\u0060\u0070\u005a\u0034\u0079\u0024\u002e\u0068\u0052\u006e\u0028\u0029\u0058\u0066\u0061\u004c\u0034\u0021\u0056\u0025\u0030\u0040\u003d\u0036\u0037\u0052\u0056\u0062\u005e\u004c\u0072\u002c\u0023\u0052\u0059\u0028\u004b\u004a\u0050\u0070\u0060\u0047\u0024\u0045\u0024\u004a\u0048\u007b\u007b\u0075\u0038\u005d\u0038\u005d\u0073\u0042\u0047\u0076\u003c\u0071\u006c\u0029\u0064\u004a\u0028\u007e\u0040\u002e\u004b\u0059\u0021\u0050\u0051\u0030\u0058\u006a\u005c\u0062\u003f\u003a\u005e\u0060\u0072\u0026\u006d\u0032\u006e\u004b\u007e\u003d\u0035\u004b\u0038\u0051\u003f\u0061\u0063\u0045\u005e\u003e\u0078\u0022\u0025\u003e\u0058\u0036\u0047\u0066\u0037\u005b\u0075\u005c\u0063\u0063\u0050\u0051\u0027\u0066\u0047\u0028\u0061\u0034\u006c\u006f\u003d\u0077\u0038\u002b\u0041\u002e\u003e\u006d\u0034\u0026\u0070\u003c\u0067\u0062\u0038\u0056\u0066\u0033\u0046\u002e\u005d\u002d\u0077\u0020\u004b\u006f\u0038\u006b\u002a\u0020\u007c\u0075\u0026\u006e\u004b\u0054\u0048\u003b\u0047\u0069\u0034\u0077\u0027\u002f\u0038\u005d\u0076\u005d\u002f\u0079\u007d\u003c\u002d\u005e\u0072\u0037\u007e\u002e\u0022\u0032\u007e\u004b\u0025\u004c\u0057\u0066\u004e\u003a\u0074\u0057\u0062\u0070\u0021\u0047\u0053\u002d\u005d\u004a\u003e\u0027\u0027\u005d\u007c\u002f\u0073\u003f\u007c\u0053\u0045\u005d\u0034\u004d\u006e\u0065\u003f\u0066\u0064\u0036\u007e\u0058\u0053\u0059\u004c\u0022\u0073\u004e\u0059\u007c\u0065\u0026\u0075\u003d\u005d\u003f\u0079\u0027\u0070\u002e\u0020\u0053\u007e\u0022\u0039\u0062\u0079\u0072\u002f\u006c\u0024\u0071\u0026\u0063\u0050\u003e\u004c\u006e\u0060\u0068\u0025\u0041\u0066\u0076\u0066\u005c\u0071\u0072\u0058\u0076\u005f\u0036\u003b\u0076\u0021\u003e\u0034\u0066\u003e\u007b\u0043\u0073\u005d\u0044\u002e\u0048\u004b\u0025\u0048\u006f\u004f\u0064\u003b\u003b\u0038\u002d\u0038\u0031\u0072\u004b\u0047\u0075\u0076\u0024\u004b\u005d\u0063\u0057\u006f\u005d\u0073\u0057\u007a\u005c\u0047\u0026\u005b\u0078\u005d\u0045\u0038\u003d\u003d\u0065\u002c\u0077\u0042\u003a\u0039\u0078\u0022\u0076\u0029\u005e\u0070\u0051\u0030\u0025\u005e\u0073\u0035\u006e\u0061\u002a\u0049\u002c\u0036\u0067\u005b\u0077\u004f\u0066\u002b\u0046\u002b\u0056\u0053\u0062\u0035\u0075\u0034\u0070\u0052\u0023\u0047\u006f\u0051\u0055\u0060\u0055\u0027\u0070\u005a\u0078\u0079\u0078\u006b\u0043\u0035\u005d\u0064\u004d\u006c\u003a\u0045\u0067\u002c\u0032\u0053\u0069\u0068\u004d\u0037\u007b\u0023\u0067\u0062\u002c\u007c\u0026\u003f\u0029\u005a\u0029\u0075\u0056\u0041\u004e\u0028\u007d\u005d\u0070\u002d\u0043\u0079\u0059\u0068\u0037\u0049\u004b\u0027\u0051\u002b\u0037\u005e\u005d\u0077\u0077\u006a\u004e\u0030\u0053\u006d\u0036\u0047\u0057\u0064\u0058\u003c\u0064\u0022\u004c\u006c\u0028\u002c\u007d\u0068\u0067\u0034\u007e\u0059\u002c\u0063\u0076\u0046\u0058\u0065\u0044\u0024\u0022\u0077\u004c\u0035\u0057\u003f\u0057\u002a\u0064\u0045\u0070\u007d\u005e\u0040\u0046\u004b\u003a\u0041\u0024\u002a\u0041\u002f\u0073\u002e\u003a\u0025\u006b\u0048\u0072\u005d\u0033\u0039\u0059\u0040\u004d\u003e\u0050\u0035\u007d\u0066\u003c\u006c\u003f\u0055\u0066\u0042\u006a\u0059\u003a\u0027\u005f\u0075\u006b\u004b\u0037\u0078\u004a\u0070\u0025\u0059\u006b\u0047\u0037\u004a\u0047\u0054\u003a\u0038\u007e\u005c\u007b\u007b\u004f\u0046\u0059\u0069\u0033\u0051\u0054\u0034\u0078\u0048\u0041\u0068\u0035\u007d\u0045\u005e\u0049\u003c\u0048\u0057\u0062\u002f\u0034\u0079\u0041\u003a\u0063\u0056\u0064\u002a\u0067\u007c\u002d\u005e\u0028\u0072\u0037\u0025\u0040\u0026\u0040\u0075\u002c\u0062\u0078\u0068\u0067\u005e\u0030\u0061\u0041\u0053\u0022\u0025\u0049\u0035\u0029\u007e\u0038\u0062\u002e\u004b\u0050\u007e\u003a\u0046\u0056\u0034\u004d\u0073\u0037\u007e\u0023\u0051\u0024\u0064\u005f\u002c\u004b\u0036\u0060\u005e\u003c\u005d\u0075\u004d\u0064\u0035\u0028\u0069\u0053\u0038\u007b\u002b\u0059\u005f\u0020\u002e\u0073\u0033\u0043\u0056\u005f\u0036\u005e\u0079\u0062\u0047\u006c\u0020\u0026\u0075\u0021\u0069\u0028\u0051\u002a\u0030\u007c\u005e\u0027\u005a\u005c\u0061\u0071\u0057\u0036\u0048\u0048\u0057\u0021\u004a\u003b\u0034\u006f\u0057\u003a\u0056\u0062\u0026\u0057\u0049\u0032\u006e\u0040\u006e\u0066\u007a\u0036\u0028\u0045\u0049\u0020\u0033\u0033\u0038\u007c\u0044\u0043\u005c\u0077\u0034\u0033\u0076\u0040\u0046\u0030\u0052\u0071\u0050\u0078\u005b\u0045\u0067\u007b\u003d\u0033\u0049\u003c\u0047\u0079\u002d\u006e\u0078\u0034\u0043\u0070\u0042\u007c\u0033\u0065\u003a\u006e\u0028\u0070\u006b\u0032\u003e\u0071\u0059\u0059\u0045\u0046\u0054\u0054\u0047\u003b\u0025\u0060\u0048\u006f\u0063\u0054\u0065\u004e\u0074\u0079\u0032\u0063\u0068\u003b